import sympy
import math
from sympy import ZZ, QQ
from sympy.abc import x, y, z

# Top-level setup for potential witness expressions
Z = ZZ
Z2 = 2
Z3 = 3
Z4 = 4
Z5 = 5
Z6 = 6
Z7 = 7
Z8 = 8
Z9 = 9
Z10 = 10

N_HYP = 2
NEG_Q_INDEX = 2

CONDITION_LABELS = [
    "H_1: R is a commutative ring with identity",
    "H_2: P is a prime ideal of R",
    "¬Q: x is not an element of P"
]

def conditions(witness) -> list[bool]:
    try:
        # Parse witness. We expect a tuple (n, p, x) representing:
        # R = Z/nZ (with n=0 meaning Z)
        # P = ideal generated by p
        # x = element of R
        # Alternatively, (p, x) assumes R = Z.
        if isinstance(witness, dict):
            n_raw = witness.get('n', witness.get('R', 0))
            p_raw = witness.get('p', witness.get('P', 0))
            x_raw = witness.get('x', 0)
        elif isinstance(witness, (tuple, list)):
            if len(witness) == 3:
                n_raw, p_raw, x_raw = witness
            elif len(witness) == 2:
                n_raw = 0
                p_raw, x_raw = witness
            else:
                return [False, False, False]
        else:
            return [False, False, False]

        # Parse n
        if n_raw in (ZZ, 'ZZ', 'Z', 0):
            n = 0
        elif n_raw in (QQ, 'QQ', 'Q'):
            n = 'QQ'
        elif isinstance(n_raw, str) and n_raw.startswith('Z') and len(n_raw) > 1:
            try:
                n = int(n_raw[1:])
            except ValueError:
                n = int(n_raw)
        else:
            n = int(n_raw)
            
        # Parse p
        if hasattr(p_raw, 'gens'):
            gens = p_raw.gens
            if len(gens) == 1:
                p = int(gens[0])
            else:
                return [False, False, False]
        elif isinstance(p_raw, (set, list, tuple)):
            if len(p_raw) == 1:
                p = int(list(p_raw)[0])
            else:
                return [False, False, False]
        else:
            p = int(p_raw)
            
        # Parse x
        if n == 'QQ':
            x_val = x_raw
        else:
            x_val = int(x_raw)
            
    except Exception:
        return [False, False, False]

    # Special case for the field of rational numbers
    try:
        if n == 'QQ':
            h1_ok = True
            h2_ok = (p == 0)
            in_P = (x_val == 0)
            neg_q_ok = not in_P
            return [h1_ok, h2_ok, neg_q_ok]
    except Exception:
        pass

    # H_1: R is a commutative ring with identity
    # Z/nZ is always a commutative ring. It has an identity if it's not the zero ring (n != 1).
    try:
        h1_ok = (abs(n) != 1)
    except Exception:
        h1_ok = False

    # H_2: P is a prime ideal of R
    # In Z/nZ, the ideal (p) is prime iff gcd(n, p) is prime, or gcd(n, p) == 0 (which means n=0, p=0).
    try:
        g = math.gcd(n, p)
        h2_ok = sympy.isprime(g) or g == 0
    except Exception:
        h2_ok = False

    # ¬Q: x is not an element of P
    # x is in (p) mod n iff x is a multiple of gcd(n, p).
    try:
        if g == 0:
            in_P = (x_val == 0)
        else:
            in_P = (x_val % g == 0)
        neg_q_ok = not in_P
    except Exception:
        neg_q_ok = False

    return [h1_ok, h2_ok, neg_q_ok]